"""Record the preregistered global-motion gate and its separate post-hoc counterexample."""
from pathlib import Path
from datetime import datetime
from zoneinfo import ZoneInfo
import hashlib, json, shutil, sys
ROOT=Path(__file__).resolve().parents[1]; OUT=ROOT/'runs/flyvis_still_robust_gate_20261105'; sys.path.insert(0,str(ROOT))
from scripts.obsidian_system_problems import load,problem_path
from scripts.obsidian_fundamental_overview import build
from scripts.audit_fundamental_obsidian import audit
def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 r=json.loads((OUT/'report.json').read_text(encoding='utf-8')); a=json.loads((OUT/'independent_audit.json').read_text(encoding='utf-8')); s=json.loads((OUT/'local_motion_stress.json').read_text(encoding='utf-8'))
 assert r['preliminary_gate'] and a['passed'] and a['report_sha256']==sha(OUT/'report.json') and s['post_hoc'] and s['cases']==32 and s['false_stationary']==24 and s['protocol_report_sha256']==sha(OUT/'report.json')
 msg=('Заранее заданная проверка признака на синтетическом глобальном движении и шуме пройдена: из 256 условий движения ни одно не принято за покой; 128 условий с однотонной сценой оставлены неопределёнными. На 32 условиях покоя с фактурой коррекция разрешена. Четыре исходных изображения использованы для настройки и четыре других — для оценки; последовательности внутри одной сцены зависимы. Независимый пересчёт признаков и решений совпал. Дополнительная проверка, проведённая после основного результата без подбора порога: движущийся на неподвижном фоне искусственный объект ошибочно признан покоем в 24 из 32 условий; в 8 случаях движение обнаружено. Этот контрпример не измеряет частоту ошибок на реальном видео.')
 refs=['runs/flyvis_still_robust_gate_20261105/'+x for x in ('protocol.json','report.json','independent_audit.json','local_motion_stress.json')]
 (OUT/'РЕЗУЛЬТАТ.md').write_text('# Проверка признака неподвижности для FlyVis\n\n'+msg+'\n\nПроверены только признаки из кадров, не полная FlyVis и не трекер. С7 остаётся открытой. Встроенное правило в модель не внедрено; HOTA не измерена. Локальная проверка выполнена после основного опыта и не является заранее зарегистрированным критерием.\n\nИсточники: '+', '.join('`'+x+'`' for x in refs)+'.\n',encoding='utf-8')
 cat=ROOT/'experiments/project_history.json'; d=json.loads(cat.read_text(encoding='utf-8')); c=next(x for x in d['experiments'] if x['id']=='flyvis_robust_still_gate_v1'); assert c['state']=='planned'
 c.update(state='inconclusive',done=datetime.now(ZoneInfo('Europe/Moscow')).date().isoformat(),obtained=msg+' Источники: '+', '.join(refs)+'.',interpretation='Ограниченный заранее заданный критерий на глобальных сдвигах выполнен, но последующий контрпример показывает, что глобальное правило может не заметить локальное движение.',decision='Не применять как решение проблемы С7; искать причинный признак локального движения и проверять на новых данных.',cannot_claim='Это не проверка полной FlyVis, реального трекера или HOTA; статистика на зависимых синтетических случаях не является оценкой ошибок на реальных видео.')
 c['acceptance'][0].update(met=True,evidence=refs[1]+':checks и '+refs[2]); c['evidence'] += [dict(kind='json',ref=x,claim='Измерение признака или независимая проверка') for x in refs[1:]]; cat.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 prob=ROOT/'experiments/system_problems.json'; shutil.copy2(prob,OUT/'system_problems_before.json'); d=json.loads(prob.read_text(encoding='utf-8')); item=next(x for x in d['problems'] if x['id']=='С7'); item['cases'].append(dict(date=datetime.now(ZoneInfo('Europe/Moscow')).date().isoformat(),fact=msg,evidence=refs)); item['cards'].append(c['id'])
 for x in refs:item['evidence'].append(dict(source=x,sha256=sha(ROOT/x),claim='Проверка неподвижности на глобальном движении и локальный контрпример'))
 prob.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 plan=ROOT/'dissertation/ЕДИНЫЙ_ПЛАН.md'; raw=plan.read_bytes(); marker='## Журнал изменений'.encode(); nl=b'\r\n' if marker+b'\r\n' in raw else b'\n'; now=datetime.now(ZoneInfo('Europe/Moscow')); entry=f'\n**{now:%d.%m.%Y, %H:%M} MSK** — Проверка признака неподвижности и локальный контрпример\n\n{msg} Источники: '+', '.join('`'+x+'`' for x in refs)+'. Полная FlyVis и HOTA не проверены; С7 открыта.\n\n'; assert raw.count(marker+nl)==1; plan.write_bytes(raw.replace(marker+nl,marker+nl+entry.encode(),1))
 vault=ROOT/'ObsidianFlyVis'; stage=OUT/'vault_checked'; backup=OUT/'vault_before'; assert not stage.exists() and not backup.exists(); shutil.copytree(vault,stage); shutil.copytree(vault,backup)
 before={f.relative_to(vault).as_posix():sha(f) for f in vault.rglob('*') if f.is_file()}; name=problem_path(next(x for x in load()['problems'] if x['id']=='С7'))+'.md'; preserve=[x for x in before if x.endswith('.md') and x!=name]; assert build(stage,preserve)==0
 for f in ['.obsidian/graph.json','.graph-visible.json','.generated.json']:shutil.copy2(backup/f,stage/f)
 checked=audit(stage); assert checked['note_count']==55 and checked['hypothesis_node_count']==25 and checked['problem_node_count']==10 and not checked['external_hypothesis_edges']; assert set(before)=={f.relative_to(stage).as_posix() for f in stage.rglob('*') if f.is_file()}; changed=[f for f,h in before.items() if sha(stage/f)!=h]; assert changed==[name] and all(sha(vault/f)==h for f,h in before.items()); shutil.copy2(stage/name,vault/name); done=audit(vault); assert done['hashes']==checked['hashes']; done.update(changed_files=changed,added_files=[],deleted_files=[],protected_hypotheses_byte_exact=True); (OUT/'graph_audit.json').write_text(json.dumps(done,ensure_ascii=False,indent=2)+'\n',encoding='utf-8'); print('Saved result, history and verified graph')
if __name__=='__main__':main()
